atts.custom_css:
selector { border-radius: 18px; overflow: hidden; box-shadow: 0 20px 50px rgba(2,6,23,.35); transition: transform .3s ease, box-shadow .3s ease; }
selector:hover { transform: translateY(-4px); box-shadow: 0 28px 60px rgba(2,6,23,.45); }
selector img { transition: transform .5s ease; }
selector:hover img { transform: scale(1.05); }
